export const meta = {
  name: 'plans-amend-probe-and-slice3',
  description: 'Move the isolated value probe into slice-2 sub-slice 2b3; fix the slice-3 plan (R3-1, leftovers, coverage-audit items, 3p on top of 2b3); independent cross-plan check; fix + recheck if needed',
  phases: [{ title: 'Amend' }, { title: 'Check' }, { title: 'Fix' }, { title: 'Recheck' }],
}
const R = '/home/zhengyew/telelean'
const S = '/tmp/claude-1000/-home-zhengyew-telelean/20626c17-0334-4498-ad86-9dc24b7010ed/scratchpad'
const SPEC = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/01_spec_v4.md'
const AP = R + '/verbatim_prompt_log/bundle_21/user_requested_documents/02_autopilot_decisions.md'
const P2 = R + '/docs/slice2-plan.md'
const P3 = S + '/plans/slice3-plan.md'
const OPEN3 = S + '/plans/slice3_open_after_ultra.json'
const COV = S + '/plans/slice3_coverage_items.md'
const AUDIT = R + '/verbatim_prompt_log/bundle_21/subagent_reports/spec_coverage_audit/coverage_audit.md'
const ULTRA = R + '/verbatim_prompt_log/bundle_21/subagent_reports/slice3_ultra_review_workflow/agents/'
const SAFE = `SAFETY AND RESOURCE RULES (mandatory): no network, no installs, no Claude CLI, no builds, no tests, no tsc/vitest/Lean runs (other agents are building slice 2 in the same working tree right now). Never change git state (read-only git is fine). Never touch ${R}/packages/extension/dist or out. Never send, post, upload or publish anything. Read-only everywhere except the file(s) your task names.`
const CONC = `CONCURRENCY RULE for ${P2}: builders of slice 2 append lines to its §8 change log while you work. Edit it ONLY with small exact-string replacements (the Edit tool), re-reading the region right before each edit; never rewrite or Write the whole file; never touch §8 lines you did not write.`
const CTX = `Context: telelean (${R}) is a VS Code extension (packages/core, runner, extension, webview) that shows a user's beliefs as cards backed by Lean 4 files; Claude formalises and proves; a non-LLM gate decides what counts. Spec v4.1: ${SPEC}; autopilot decisions ${AP}. Slice 1 is built; slice 2 (plan ${P2}) is being built sub-slice by sub-slice: 2a1, 2a2 (reviewed as "2a"), 2b1a are done, 2b1b is being built now, then 2b2, 2c1, 2c2, and later 2b3, 2d, 2e, 2f, 2g, 2h, 2i. Slice 3 (FROZEN) is planned in ${P3}, which just went through an ultra review (reports in ${ULTRA}). A spec coverage audit (${AUDIT}) produced items for slice 3 (${COV}).

THE PROBE PROBLEM (ultra review finding S3-1, confirmed by a refuter; read find_checks and refute_checks in ${ULTRA}): the value probe that yields DeclFacts.valueConsts (slice 1d) and that slice-2's 2b3 extends with typeConsts runs as an #eval inside the check file, which imports the model. Its own code (IO.println, String ++, for/while loops, toString) is therefore elaborated with the model's instances in scope, so a high-priority instance in the model (e.g. ToString String) can forge the probe's output: valueConsts, typeConsts, and (in slice 3) meaningKey. Slice 1's B.2/bands, slice 2's D2-41 constant sets, RV-5 dependencies and B.2 read this probe today. The slice-3 plan's fix (D3-52, §2.1 "The probe is isolated", §1.1 3p): run the probe as its own Lean job whose file imports only Lean.CoreM and Lean.Util.FoldConsts and loads the model's .olean files with Lean.importModules at run time (G0 bans initialize, so importing runs no model code), with a fallback (hashing leanexport's output) if importModules cannot work on the pinned toolchain; the check file's in-file probe and AP-21's second run go; the ghost check's in-file probe is kept as a stated residual.`

phase('Amend')
const a2 = await agent(`${SAFE} You edit exactly ONE file: ${P2}. ${CONC}\n\n${CTX}\n\nYOUR TASK: move the probe isolation into slice 2, sub-slice 2b3 ("the type-constant probe and the runner engine"; 2b3 has not started), so that slice 2's own checks never read a forgeable probe. Read first: ${P3} §2.1 (the isolated probe, its normalisation and the facts marker), D3-52 and §1.1's 3p entry; ${P2} §1, §1.1 (2b3 entry and its split 2b3a/2b3b), §2.1 (DeclFacts.typeConsts and the probe), §6.1 (2b3 tests), §7.2 (D2-41) and §8; ${AP} AP-21; and the code: packages/runner/src/semantic/checkFile.ts (valueProbeLines), refresh.ts, and how the runner runs Lean (runLean). Then amend ${P2}: (1) §2.1: the probe that gives valueConsts AND typeConsts runs as its own isolated Lean job (as D3-52 describes; precise enough for a builder: file contents, how it is run and parsed, what happens when it fails — fail closed: a state whose probe failed because of the state itself is refused at checks with a facts finding naming the cause, as the slice-3 plan's S3-2 fix says; B and pre-isolation records may be approx), and the in-file probe is removed from the check file (say what happens to AP-21's second run and to the ghost check's in-file probe, with any residual stated); (2) §1.1's 2b3 entry (2b3a: the isolated probe with valueConsts and typeConsts, its measurement, and the regeneration of test-fixtures/semantic/recorded/* and core's Spyro facts with it; 2b3b unchanged); (3) §6.1's 2b3 tests: the isolation (a model with a high-priority ToString String instance and a ForIn instance cannot change the probe's output: cheat built with real Lean), the importModules check, the fail-closed cases, recordings regenerated; (4) a §7.2 decision D2-75 "AUTOPILOT DECISION:" with the alternative (keep the in-file probe and accept the residual) and how to reverse it; (5) one §8 line "orchestrator (slice-3 ultra review S3-1, AP-30): …". Keep every existing contract name; add, do not rename. Return: what you changed (section by section) and anything the slice-3 plan must now say differently.`, { label: 'amend:slice2-probe', phase: 'Amend' })

const a3 = await agent(`${SAFE} You edit exactly ONE file: ${P3} (no concurrency there).\n\n${CTX}\n\nThe slice-2 plan was just amended so that 2b3 builds the isolated probe for valueConsts and typeConsts (the amender's report follows). YOUR TASK on ${P3}:\n(a) Make 3p build on 2b3's isolated probe: 3p only adds meaningKey (with §2.1's normalisation) to that job, plus the recordings/Spyro facts regeneration for meaningKey; remove from 3p what 2b3 now does; keep D3-52 consistent (it now extends D2-75).\n(b) Fix every finding left open by the ultra review's last recheck (JSON in ${OPEN3}; R3-1 is major: heldAtJudge is set only on records reconcile leaves in review, but records are returned to review or accepted without a judge in between; fix it soundly and simply, e.g. compute the held map at Accept time from the last judged facts of the current state, or refuse the Accept until a judge has run, whichever is simplest and never fails open).\n(c) Apply all ten items of ${COV} (they follow the orchestrator's AP-29 decisions; the audit report ${AUDIT} has the evidence).\nFor each change update every section that depends on it (scopes, contracts, tests, decisions §7, cheats §6.2) and add dated §8 lines ("orchestrator (AP-29 / AP-30): …"). Return one disposition per item: (a), each open finding id, and each coverage item 1-10: done / partly / not done (why).\n\n=== SLICE-2 AMENDER'S REPORT ===\n${a2}\n=== END ===`, { label: 'amend:slice3', phase: 'Amend' })

const FIND = { type: 'object', properties: { summary: { type: 'string' }, findings: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, severity: { type: 'string', enum: ['blocker', 'major', 'minor', 'nit'] }, plan: { type: 'string', enum: ['slice2', 'slice3', 'both'] }, where: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } }, required: ['id', 'severity', 'plan', 'where', 'problem', 'fix'] } } }, required: ['summary', 'findings'] }
phase('Check')
const chk = await agent(`${SAFE} Read-only: you edit nothing.\n\n${CTX}\n\nTwo amenders just changed the plans (their reports follow). Check, adversarially: (1) the slice-2 amendment (search ${P2} for "D2-75", "AP-30", 2b3 and §2.1): is the isolated probe sound (could model content still influence its output: notation, macros, attributes, environment extensions, initialize, import order, olean contents, the ghost check's residual)? Is it buildable within 2b3a by one agent, with tests precise enough, consistent with slice 2's contracts and the code built so far (packages/core/src/review/*, packages/runner/src/semantic/*)? Is failing closed handled at every purpose without blocking legitimate states? (2) the slice-3 amendments: is R3-1 fixed soundly; are the other open findings and all ten coverage items (${COV}) really applied, consistently across sections; is 3p consistent with 2b3? (3) the two plans agree with each other. Report only real problems, each with a concrete fix and which plan it is in.\n\n=== SLICE-2 AMENDER ===\n${a2}\n=== SLICE-3 AMENDER ===\n${a3}\n=== END ===`, { label: 'check:amendments', phase: 'Check', schema: FIND })

let open = chk ? chk.findings : []
const sev = (fs) => fs.filter((f) => f.severity === 'blocker' || f.severity === 'major').length
log(`check: ${open.length} findings, ${sev(open)} blocker/major`)
const rounds = []
for (let round = 1; round <= 2 && open.length > 0; round++) {
  phase('Fix')
  const fx = await agent(`${SAFE} You edit ${P2} (only under the CONCURRENCY RULE) and ${P3}. ${CONC}\n\n${CTX}\n\nFix every finding below in the plan it names (blockers and majors must; minors when cheap and clearly right); if a finding is wrong, change nothing for it and say why. Keep both plans consistent; add dated §8 lines. Return one disposition per finding.\n\n=== FINDINGS ===\n${JSON.stringify(open, null, 1)}`, { label: `fix:r${round}`, phase: 'Fix' })
  phase('Recheck')
  const re = await agent(`${SAFE} Read-only.\n\n${CTX}\n\nA fixer just handled the findings below (its report follows). Check each is really fixed or rightly rejected (re-raise with the same id if not), then look for NEW blocker/major problems the fixes introduced, in either plan. Report only real problems with concrete fixes.\n\n=== FINDINGS ===\n${JSON.stringify(open, null, 1)}\n=== FIXER ===\n${fx}\n=== END ===`, { label: `recheck:r${round}`, phase: 'Recheck', schema: FIND })
  rounds.push({ round, findings: open, fix: fx, recheck: re })
  open = re ? re.findings : []
  log(`round ${round}: ${open.length} open, ${sev(open)} blocker/major`)
  if (sev(open) === 0) break
}
return { a2, a3, check: chk, rounds, open }
